  primary: "2C5282",      // Dark blue
  success: "276749",      // Green
  warning: "C05621",      // Orange
  danger: "C53030",       // Red
  headerBg: "EBF8FF",     // Light blue
  lightGray: "F7FAFC",
  border: "CBD5E0"
