// Table border helper
const createBorder = (color = COLORS.border) => ({
  style: BorderStyle.SINGLE, size: 1, color: color
});

const borders = {
  top: createBorder(),
  bottom: createBorder(),
  left: createBorder(),
  right: createBorder()
};

// Helper to create metric row
const createMetricRow = (label, value, status, isHeader = false) => {
  const bgColor = isHeader ? COLORS.headerBg : "FFFFFF";
  const textBold = isHeader;

  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 4000, type: WidthType.DXA },
        shading: { fill: bgColor, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({
          children: [new TextRun({ text: label, bold: textBold, font: "Arial", size: 20 })]
        })]
      }),
      new TableCell({
        borders,
        width: { size: 2500, type: WidthType.DXA },
        shading: { fill: bgColor, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: value, bold: textBold, font: "Arial", size: 20 })]
        })]
      }),
      new TableCell({
        borders,
        width: { size: 2860, type: WidthType.DXA },
        shading: { fill: bgColor, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 120, right: 120 },
        children: [new Paragraph({
          alignment: AlignmentType.CENTER,
          children: [new TextRun({ text: status, bold: textBold, font: "Arial", size: 20 })]
        })]
      })
    ]
  });
};

